const triggerItem = $("01 Input Trigger").item;
const input = triggerItem.json || {};
const jobRow = ($json && $json.job_id) ? $json : null;
const binaryObj = triggerItem.binary && triggerItem.binary.data ? triggerItem.binary.data : null;

let errorCode = null;
let errorMessage = null;

if (!input.jobId) {
  errorCode = "MISSING_JOB_ID";
  errorMessage = "jobId is required for media upload.";
} else if (!input.assetKey) {
  errorCode = "MISSING_ASSET_KEY";
  errorMessage = "assetKey is required for media upload.";
} else if (!input.assetType) {
  errorCode = "MISSING_ASSET_TYPE";
  errorMessage = "assetType is required for media upload.";
} else if (!jobRow) {
  errorCode = "JOB_NOT_FOUND";
  errorMessage = "No content_jobs row found for jobId " + input.jobId;
} else if (!jobRow.api_base_url) {
  errorCode = "SITE_CONFIG_MISSING";
  errorMessage = "site_configs api_base_url is missing for site_key " + jobRow.site_key;
} else if (!binaryObj || !binaryObj.data) {
  errorCode = "MISSING_BINARY_DATA";
  errorMessage = "No binary image input supplied for media upload.";
}

return {
  json: {
    jobId: input.jobId,
    assetKey: input.assetKey,
    assetType: input.assetType,
    language: input.language || "ar",
    apiBaseUrl: jobRow ? jobRow.api_base_url : null,
    width: input.width || null,
    height: input.height || null,
    fileSizeBytes: input.fileSizeBytes || null,
    checksum: input.checksum || null,
    mimeType: input.mimeType || "image/webp",
    ok: errorCode === null,
    errorCode,
    errorMessage
  },
  binary: triggerItem.binary
};

const prev = $("02B Validate Pre-Upload Requirements and Preserve Binary").item;
const prevJson = prev.json;
const resp = $json || {};
const statusCode = resp.statusCode || (resp.headers ? 200 : 0);
const body = resp.body !== undefined ? resp.body : resp;
const isSuccess = (statusCode >= 200 && statusCode < 300) && body && body.mediaId && body.finalUrl;

if (!isSuccess) {
  return {
    json: {
      ok: false,
      jobId: prevJson.jobId,
      assetKey: prevJson.assetKey,
      assetType: prevJson.assetType,
      errorCode: "MEDIA_UPLOAD_FAILED",
      errorMessage: (body && body.message) ? body.message : "Custom Site API media binary upload returned HTTP " + statusCode + "."
    },
    binary: prev.binary
  };
}

return {
  json: {
    ok: true,
    jobId: prevJson.jobId,
    assetKey: prevJson.assetKey,
    assetType: prevJson.assetType,
    finalUrl: body.finalUrl,
    mediaId: body.mediaId,
    language: prevJson.language,
    width: prevJson.width || body.width || null,
    height: prevJson.height || body.height || null,
    fileSizeBytes: prevJson.fileSizeBytes || body.fileSizeBytes || null,
    mimeType: prevJson.mimeType || body.mimeType || "image/webp",
    checksum: prevJson.checksum || body.checksum || null,
    approvalStatus: "approved"
  },
  binary: prev.binary
};

const prevItem = $("04 Evaluate Media Upload Result").item;
const m = prevItem.json;
const norm = {
  success: true,
  jobId: m.jobId,
  status: "ASSET_UPLOADED",
  message: "Media asset binary uploaded to Custom Site API and registered in database successfully.",
  data: {
    assetKey: m.assetKey,
    assetType: m.assetType,
    mediaId: m.mediaId,
    finalUrl: m.finalUrl,
    width: m.width,
    height: m.height,
    fileSizeBytes: m.fileSizeBytes,
    mimeType: m.mimeType,
    checksum: m.checksum
  },
  warnings: [],
  errors: [],
  nextAllowedActions: ["create_preview"]
};
return {
  json: {
    jobId: m.jobId,
    assetKey: m.assetKey,
    assetType: m.assetType,
    language: m.language,
    finalUrl: m.finalUrl,
    mediaId: m.mediaId,
    width: m.width,
    height: m.height,
    fileSizeBytes: m.fileSizeBytes,
    checksum: m.checksum,
    mimeType: m.mimeType,
    normalized: norm
  },
  binary: prevItem.binary
};

const j = $json || {};
const code = j.errorCode || "MEDIA_UPLOAD_FAILED";
const message = j.errorMessage || "Custom Site API media upload failed.";
return {
  json: {
    success: false,
    jobId: j.jobId || null,
    assetKey: j.assetKey || null,
    assetType: j.assetType || null,
    status: "FAILED",
    message,
    data: null,
    warnings: [],
    errors: [{ code, language: null, path: null, message }],
    nextAllowedActions: ["retry", "cancel"]
  },
  binary: $input.item ? $input.item.binary : undefined
};
